/**
 * Self-contained integration test (no express dependency needed).
 * We monkey-patch require('express') with a minimal stand-in so the
 * full app.js startup path — including loadTlsCredentials(), startHttp(),
 * startHttps(), and the fallback warning — can be exercised.
 */
'use strict';

const Module   = require('module');
const http     = require('http');
const https    = require('https');
const fs       = require('fs');
const path     = require('path');
const crypto   = require('crypto');
const { execSync } = require('child_process');

// ── Minimal express stub ───────────────────────────────────────────────────────
const originalLoad = Module._load;
Module._load = function (request, ...args) {
  if (request === 'express') {
    const routes = {};
    const app = (req, res) => {
      const handler = routes[req.url];
      if (handler) handler(req, res);
      else { res.writeHead(404); res.end('not found'); }
    };
    app.get = (path, fn) => { routes[path] = fn; };
    return () => app;           // express() returns app
  }
  return originalLoad.call(this, request, ...args);
};

// ── Generate a self-signed cert for HTTPS tests ────────────────────────────────
const tmpDir  = fs.mkdtempSync('/tmp/tls-test-');
const certFile = path.join(tmpDir, 'cert.pem');
const keyFile  = path.join(tmpDir, 'key.pem');

try {
  execSync(
    `openssl req -x509 -newkey rsa:2048 -keyout ${keyFile} -out ${certFile}` +
    ` -days 1 -nodes -subj "/CN=localhost"`,
    { stdio: 'pipe' }
  );
} catch (_) { /* openssl not available – TLS tests will be skipped */ }

const opensslOK = fs.existsSync(certFile) && fs.existsSync(keyFile);

// ── Helper: make a plain HTTP GET and collect the body ────────────────────────
function httpGet(port, urlPath) {
  return new Promise((resolve, reject) => {
    http.get({ host: 'localhost', port, path: urlPath }, (res) => {
      let body = '';
      res.on('data', d => body += d);
      res.on('end', () => resolve({ status: res.statusCode, body }));
    }).on('error', reject);
  });
}

// ── Helper: HTTPS GET (skip cert validation for self-signed) ──────────────────
function httpsGet(port, urlPath) {
  return new Promise((resolve, reject) => {
    https.get(
      { host: 'localhost', port, path: urlPath, rejectUnauthorized: false },
      (res) => {
        let body = '';
        res.on('data', d => body += d);
        res.on('end', () => resolve({ status: res.statusCode, body }));
      }
    ).on('error', reject);
  });
}

// ── Run all tests ─────────────────────────────────────────────────────────────
async function runTests() {
  let passed = 0, failed = 0;

  function ok(label, cond) {
    if (cond) { console.log(`  ✓  ${label}`); passed++; }
    else       { console.error(`  ✗  ${label}`); failed++; }
  }

  // ── Suite 1: config.js unit tests ─────────────────────────────────────────
  console.log('\n── Suite 1: config.js ────────────────────────────────────────');

  // (a) defaults with no env vars
  delete process.env.HTTP_PORT; delete process.env.HTTPS_PORT;
  delete process.env.TLS_CERT_PATH; delete process.env.TLS_KEY_PATH;
  const cfg1 = requireFresh('./config');
  ok('HTTP_PORT  defaults to 3000', cfg1.HTTP_PORT  === 3000);
  ok('HTTPS_PORT defaults to 3443', cfg1.HTTPS_PORT === 3443);
  ok('TLS_ENABLED false when no paths', cfg1.TLS_ENABLED === false);
  ok('TLS_CERT_PATH is null',  cfg1.TLS_CERT_PATH === null);
  ok('TLS_KEY_PATH  is null',  cfg1.TLS_KEY_PATH  === null);

  // (b) custom ports
  process.env.HTTP_PORT = '8080'; process.env.HTTPS_PORT = '8443';
  const cfg2 = requireFresh('./config');
  ok('HTTP_PORT  honours HTTP_PORT env',  cfg2.HTTP_PORT  === 8080);
  ok('HTTPS_PORT honours HTTPS_PORT env', cfg2.HTTPS_PORT === 8443);
  delete process.env.HTTP_PORT; delete process.env.HTTPS_PORT;

  // (c) both paths supplied → TLS_ENABLED true
  process.env.TLS_CERT_PATH = '/tmp/cert.pem';
  process.env.TLS_KEY_PATH  = '/tmp/key.pem';
  const cfg3 = requireFresh('./config');
  ok('TLS_ENABLED true when both paths set', cfg3.TLS_ENABLED === true);
  ok('CERT_PATH resolved',  cfg3.TLS_CERT_PATH === path.resolve('/tmp/cert.pem'));
  ok('KEY_PATH  resolved',  cfg3.TLS_KEY_PATH  === path.resolve('/tmp/key.pem'));
  delete process.env.TLS_CERT_PATH; delete process.env.TLS_KEY_PATH;

  // (d) only one path → TLS_ENABLED false
  process.env.TLS_CERT_PATH = '/tmp/cert.pem';
  const cfg4 = requireFresh('./config');
  ok('TLS_ENABLED false when only CERT set', cfg4.TLS_ENABLED === false);
  delete process.env.TLS_CERT_PATH;

  // ── Suite 2: app.js – HTTP-only mode ──────────────────────────────────────
  console.log('\n── Suite 2: app.js HTTP-only boot ───────────────────────────');
  delete process.env.TLS_CERT_PATH; delete process.env.TLS_KEY_PATH;
  process.env.HTTP_PORT  = '13000';
  process.env.HTTPS_PORT = '13443';

  const { app: appA, httpServer: hs1, httpsServer: hts1 } = requireFresh('./app');

  await sleep(120);
  ok('httpServer  is not null',       hs1  !== null);
  ok('httpsServer is null (no certs)', hts1 === null);
  ok('httpServer  is listening',       hs1.listening);

  const r1 = await httpGet(13000, '/health');
  ok('/health returns 200', r1.status === 200);
  ok('/health body has "ok"', r1.body.includes('"ok"'));

  const r2 = await httpGet(13000, '/users');
  ok('/users returns 200', r2.status === 200);
  ok('/users body has "Alice"', r2.body.includes('Alice'));

  hs1.close();

  // ── Suite 3: app.js – HTTPS mode ──────────────────────────────────────────
  if (!opensslOK) {
    console.log('\n── Suite 3: SKIPPED (openssl not available) ─────────────────');
  } else {
    console.log('\n── Suite 3: app.js HTTP + HTTPS boot ────────────────────────');
    process.env.TLS_CERT_PATH = certFile;
    process.env.TLS_KEY_PATH  = keyFile;
    process.env.HTTP_PORT  = '13001';
    process.env.HTTPS_PORT = '13444';

    const { httpServer: hs2, httpsServer: hts2 } = requireFresh('./app');

    await sleep(200);
    ok('httpServer  is listening (HTTPS mode)', hs2.listening);
    ok('httpsServer is listening',              hts2 !== null && hts2.listening);

    const r3 = await httpGet(13001, '/health');
    ok('HTTP  /health returns 200', r3.status === 200);

    const r4 = await httpsGet(13444, '/health');
    ok('HTTPS /health returns 200', r4.status === 200);
    ok('HTTPS /health body has "ok"', r4.body.includes('"ok"'));

    const r5 = await httpsGet(13444, '/users');
    ok('HTTPS /users returns 200',         r5.status === 200);
    ok('HTTPS /users body has "Bob"',      r5.body.includes('Bob'));

    hs2.close(); hts2.close();
    delete process.env.TLS_CERT_PATH; delete process.env.TLS_KEY_PATH;

    // ── Suite 4: graceful fallback when cert files missing ─────────────────
    console.log('\n── Suite 4: graceful fallback (bad cert paths) ──────────────');
    process.env.TLS_CERT_PATH = '/nonexistent/cert.pem';
    process.env.TLS_KEY_PATH  = '/nonexistent/key.pem';
    process.env.HTTP_PORT  = '13002';
    process.env.HTTPS_PORT = '13445';

    const { httpServer: hs3, httpsServer: hts3 } = requireFresh('./app');
    await sleep(120);
    ok('HTTP still running after bad cert paths', hs3.listening);
    ok('httpsServer is null after bad cert paths', hts3 === null);

    const r6 = await httpGet(13002, '/users');
    ok('/users still reachable via HTTP', r6.status === 200);

    hs3.close();
    delete process.env.TLS_CERT_PATH; delete process.env.TLS_KEY_PATH;
  }

  // ── Summary ───────────────────────────────────────────────────────────────
  console.log(`\n── Results: ${passed} passed, ${failed} failed ─────────────────────────`);
  if (failed > 0) process.exit(1);
}

function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

function requireFresh(mod) {
  // Bust the require cache so each test gets a fresh module with current env.
  const abs = require.resolve(mod);
  delete require.cache[abs];
  // Also bust config so app.js picks up the fresh env.
  const cfgAbs = require.resolve('./config');
  delete require.cache[cfgAbs];
  return require(mod);
}

runTests().catch(err => { console.error(err); process.exit(1); });
EOF

