 * Central configuration module.
 * TLS is enabled only when both TLS_CERT_PATH and TLS_KEY_PATH are set in the
 * environment.  The certificate files are read lazily (in app.js) so that this
 * module stays side-effect-free and easy to unit-test.
 */

'use strict';

const path = require('path');

// ── Ports ─────────────────────────────────────────────────────────────────────
const HTTP_PORT  = parseInt(process.env.HTTP_PORT  || '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT || '3443', 10);

// ── TLS certificate paths ─────────────────────────────────────────────────────
const TLS_CERT_PATH = process.env.TLS_CERT_PATH || null;
const TLS_KEY_PATH  = process.env.TLS_KEY_PATH  || null;

// HTTPS is considered "available" only when *both* paths are provided.
const TLS_ENABLED = Boolean(TLS_CERT_PATH && TLS_KEY_PATH);

// ── Resolve paths relative to the project root ────────────────────────────────
const certPath = TLS_CERT_PATH ? path.resolve(TLS_CERT_PATH) : null;
const keyPath  = TLS_KEY_PATH  ? path.resolve(TLS_KEY_PATH)  : null;

// ── Exported configuration object ─────────────────────────────────────────────
module.exports = {
  HTTP_PORT,
  HTTPS_PORT,
  TLS_ENABLED,
  /** Absolute path to the PEM-encoded TLS certificate (null when TLS is off). */
  TLS_CERT_PATH: certPath,
  /** Absolute path to the PEM-encoded private key   (null when TLS is off). */
  TLS_KEY_PATH: keyPath,
};

'use strict';

/**
 * app.js
 *
 * Express application with dual HTTP / HTTPS support.
 *
 * Behaviour
 * ─────────────────────────────────────────────────────────────────────────────
 *  • Always starts an HTTP server on HTTP_PORT  (default 3000).
 *  • When TLS_CERT_PATH and TLS_KEY_PATH are set in the environment AND the
 *    files can be read successfully, also starts an HTTPS server on HTTPS_PORT
 *    (default 3443).
 *  • If either cert file is missing or unreadable the process logs a clear
 *    warning and continues in HTTP-only mode instead of crashing.
 */

const fs      = require('fs');
const http    = require('http');
const https   = require('https');
const express = require('express');
const config  = require('./config');

const app = express();

// ── Routes ────────────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ── Server startup ─────────────────────────────────────────────────────────────

/**
 * Attempt to load TLS credentials from the paths supplied in config.
 *
 * @returns {{ cert: Buffer, key: Buffer } | null}
 *   The raw file buffers on success, or null when TLS is disabled / unavailable.
 */
function loadTlsCredentials() {
  if (!config.TLS_ENABLED) {
    return null;
  }

  try {
    const cert = fs.readFileSync(config.TLS_CERT_PATH);
    const key  = fs.readFileSync(config.TLS_KEY_PATH);
    return { cert, key };
  } catch (err) {
    console.warn(
      '[HTTPS] Could not read TLS certificate files — falling back to HTTP only.\n' +
      `        TLS_CERT_PATH : ${config.TLS_CERT_PATH}\n` +
      `        TLS_KEY_PATH  : ${config.TLS_KEY_PATH}\n` +
      `        Reason        : ${err.message}`
    );
    return null;
  }
}

/**
 * Start the HTTP server (always).
 */
function startHttp() {
  const server = http.createServer(app);

  server.listen(config.HTTP_PORT, () => {
    console.log(`[HTTP]  Server listening on http://localhost:${config.HTTP_PORT}`);
  });

  server.on('error', (err) => {
    console.error(`[HTTP]  Failed to start: ${err.message}`);
    process.exit(1);
  });

  return server;
}

/**
 * Start the HTTPS server (only when valid TLS credentials are available).
 *
 * @param {{ cert: Buffer, key: Buffer }} credentials
 */
function startHttps(credentials) {
  const server = https.createServer(
    { cert: credentials.cert, key: credentials.key },
    app
  );

  server.listen(config.HTTPS_PORT, () => {
    console.log(`[HTTPS] Server listening on https://localhost:${config.HTTPS_PORT}`);
  });

  server.on('error', (err) => {
    // Non-fatal: the HTTP server is already running.
    console.error(`[HTTPS] Failed to start: ${err.message}`);
  });

  return server;
}

// ── Bootstrap ─────────────────────────────────────────────────────────────────

const tlsCredentials = loadTlsCredentials();

const httpServer  = startHttp();
const httpsServer = tlsCredentials ? startHttps(tlsCredentials) : null;

if (!tlsCredentials) {
  console.log('[HTTPS] TLS not configured — running in HTTP-only mode.');
  console.log('        Set TLS_CERT_PATH and TLS_KEY_PATH to enable HTTPS.');
}

// ── Exports (useful for testing) ──────────────────────────────────────────────

module.exports = { app, httpServer, httpsServer };

