// config.js — centralised application configuration
//
// TLS is enabled only when BOTH certificate paths are supplied via
// environment variables.  All other settings fall back to safe defaults
// so the app starts correctly in every environment without extra setup.

'use strict';

const fs   = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Resolve a raw path string and verify the file is readable.
 * Returns the resolved absolute path, or null when the value is absent /
 * the file cannot be accessed.
 *
 * @param {string|undefined} rawPath - Value from an environment variable.
 * @param {string}           label   - Human-readable name used in log messages.
 * @returns {string|null}
 */
function resolveFilePath(rawPath, label) {
  if (!rawPath || !rawPath.trim()) {
    return null;
  }

  const resolved = path.resolve(rawPath.trim());

  try {
    fs.accessSync(resolved, fs.constants.R_OK);
    return resolved;
  } catch {
    console.warn(
      `[config] Warning: ${label} path "${resolved}" is not readable — ` +
      'HTTPS will be disabled.'
    );
    return null;
  }
}

// ---------------------------------------------------------------------------
// Port configuration
// ---------------------------------------------------------------------------

const HTTP_PORT  = parseInt(process.env.HTTP_PORT  || '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT || '3443', 10);

// ---------------------------------------------------------------------------
// TLS configuration
// ---------------------------------------------------------------------------

const certPath = resolveFilePath(process.env.TLS_CERT_PATH, 'TLS_CERT_PATH');
const keyPath  = resolveFilePath(process.env.TLS_KEY_PATH,  'TLS_KEY_PATH');

// TLS is only considered available when BOTH files are present and readable.
const tlsAvailable = certPath !== null && keyPath !== null;

/**
 * Lazily load TLS file contents.
 * Files are read once on first access and then cached, so the config object
 * is cheap to construct even when HTTPS is ultimately not used.
 */
let _tlsOptions = null;

function getTlsOptions() {
  if (!tlsAvailable) return null;

  if (_tlsOptions === null) {
    try {
      _tlsOptions = {
        cert: fs.readFileSync(certPath),
        key:  fs.readFileSync(keyPath),
      };
    } catch (err) {
      console.error('[config] Failed to read TLS files:', err.message);
      return null;
    }
  }

  return _tlsOptions;
}

// ---------------------------------------------------------------------------
// Exported configuration object
// ---------------------------------------------------------------------------

module.exports = {
  /** Port for the plain-text HTTP server. */
  httpPort: HTTP_PORT,

  /** Port for the TLS-encrypted HTTPS server. */
  httpsPort: HTTPS_PORT,

  /**
   * True when both TLS_CERT_PATH and TLS_KEY_PATH point to readable files.
   * Use this flag before calling getTlsOptions() to decide whether to spin up
   * an HTTPS server at all.
   */
  tlsAvailable,

  /**
   * Returns a `{ cert, key }` object suitable for passing directly to
   * `https.createServer()`, or null when TLS is unavailable.
   */
  getTlsOptions,
};

// app.js — Express application with HTTP + optional HTTPS support
//
// Servers started:
//   • HTTP  — always, on httpPort  (default 3000, override via HTTP_PORT)
//   • HTTPS — only when TLS_CERT_PATH and TLS_KEY_PATH env vars point to
//             readable certificate/key files, on httpsPort (default 3443,
//             override via HTTPS_PORT)

'use strict';

const http    = require('http');
const https   = require('https');
const express = require('express');
const config  = require('./config');

const app = express();

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ---------------------------------------------------------------------------
// Server startup
// ---------------------------------------------------------------------------

/**
 * Start the HTTP server unconditionally.
 */
function startHttp() {
  const server = http.createServer(app);

  server.listen(config.httpPort, () => {
    console.log(`[http]  Server listening on http://localhost:${config.httpPort}`);
  });

  server.on('error', (err) => {
    console.error(`[http]  Failed to start HTTP server on port ${config.httpPort}:`, err.message);
    process.exit(1);
  });

  return server;
}

/**
 * Start the HTTPS server when TLS credentials are available.
 * Returns the server instance, or null when TLS is not configured.
 */
function startHttps() {
  if (!config.tlsAvailable) {
    console.log(
      '[https] TLS_CERT_PATH / TLS_KEY_PATH not set or unreadable — ' +
      'skipping HTTPS server.'
    );
    return null;
  }

  const tlsOptions = config.getTlsOptions();
  if (!tlsOptions) {
    // getTlsOptions() already logged the specific error.
    console.warn('[https] Could not load TLS credentials — skipping HTTPS server.');
    return null;
  }

  const server = https.createServer(tlsOptions, app);

  server.listen(config.httpsPort, () => {
    console.log(`[https] Server listening on https://localhost:${config.httpsPort}`);
  });

  server.on('error', (err) => {
    console.error(
      `[https] Failed to start HTTPS server on port ${config.httpsPort}:`,
      err.message
    );
    // A broken HTTPS listener is non-fatal; HTTP remains available.
  });

  return server;
}

const httpServer  = startHttp();
const httpsServer = startHttps();

// ---------------------------------------------------------------------------
// Exports (useful for integration tests)
// ---------------------------------------------------------------------------

module.exports = { app, httpServer, httpsServer };

