/**
 * config.js
 *
 * Central configuration module. TLS settings are read exclusively from
 * environment variables so that no secrets or file-system paths are
 * hard-coded into the application.
 *
 * Required environment variables for HTTPS:
 *   TLS_CERT_PATH  – absolute (or relative) path to the PEM certificate file
 *   TLS_KEY_PATH   – absolute (or relative) path to the PEM private-key file
 *
 * Both variables must be present and point to readable files for HTTPS to be
 * enabled. If either is missing the server starts in HTTP-only mode.
 */

'use strict';

const fs = require('fs');
const path = require('path');

// ── Port configuration ────────────────────────────────────────────────────────
const HTTP_PORT  = parseInt(process.env.HTTP_PORT  || '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT || '3443', 10);

// ── TLS certificate loading ───────────────────────────────────────────────────

/**
 * Attempt to read a file and return its contents as a Buffer.
 * Returns null (and logs a warning) if the path is falsy or unreadable.
 *
 * @param {string|undefined} filePath  Path supplied via environment variable.
 * @param {string}           label     Human-readable label used in log messages.
 * @returns {Buffer|null}
 */
function readCertFile(filePath, label) {
  if (!filePath) {
    return null;
  }

  const resolved = path.resolve(filePath);

  try {
    const contents = fs.readFileSync(resolved);
    console.log(`[config] Loaded ${label}: ${resolved}`);
    return contents;
  } catch (err) {
    console.warn(
      `[config] WARNING: Could not read ${label} at "${resolved}": ${err.message}`
    );
    return null;
  }
}

const certBuffer = readCertFile(process.env.TLS_CERT_PATH, 'TLS certificate');
const keyBuffer  = readCertFile(process.env.TLS_KEY_PATH,  'TLS private key');

/**
 * tlsOptions is non-null only when both the certificate and the private key
 * were loaded successfully. Pass it directly to `https.createServer()`.
 *
 * @type {{ cert: Buffer, key: Buffer }|null}
 */
const tlsOptions =
  certBuffer && keyBuffer ? { cert: certBuffer, key: keyBuffer } : null;

if (tlsOptions) {
  console.log('[config] TLS configuration loaded — HTTPS will be enabled.');
} else {
  console.log(
    '[config] TLS_CERT_PATH / TLS_KEY_PATH not set or unreadable — ' +
    'falling back to HTTP-only mode.'
  );
}

// ── Exports ───────────────────────────────────────────────────────────────────
module.exports = {
  HTTP_PORT,
  HTTPS_PORT,
  /** @type {{ cert: Buffer, key: Buffer }|null} */
  tlsOptions,
};

/**
 * app.js
 *
 * Express application with dual HTTP / HTTPS support.
 *
 * Behaviour
 * ─────────
 *  • Always starts an HTTP server on HTTP_PORT (default 3000).
 *  • When TLS_CERT_PATH and TLS_KEY_PATH environment variables point to
 *    readable PEM files, also starts an HTTPS server on HTTPS_PORT
 *    (default 3443).
 *  • Falls back to HTTP-only mode when certificates are unavailable,
 *    so development environments work without any extra setup.
 */

'use strict';

const http    = require('http');
const https   = require('https');
const express = require('express');

const { HTTP_PORT, HTTPS_PORT, tlsOptions } = require('./config');

const app = express();

// ── Routes ────────────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ── Server startup ────────────────────────────────────────────────────────────

/**
 * Start the HTTP server (always).
 */
function startHttpServer() {
  return new Promise((resolve, reject) => {
    const server = http.createServer(app);

    server.on('error', (err) => {
      console.error(`[http] Failed to start on port ${HTTP_PORT}: ${err.message}`);
      reject(err);
    });

    server.listen(HTTP_PORT, () => {
      console.log(`[http]  Server listening on http://localhost:${HTTP_PORT}`);
      resolve(server);
    });
  });
}

/**
 * Start the HTTPS server when TLS options are available.
 * Resolves with null when certs are not configured.
 */
function startHttpsServer() {
  if (!tlsOptions) {
    // Certs not configured — skip HTTPS silently (config.js already logged why).
    return Promise.resolve(null);
  }

  return new Promise((resolve, reject) => {
    const server = https.createServer(tlsOptions, app);

    server.on('error', (err) => {
      console.error(`[https] Failed to start on port ${HTTPS_PORT}: ${err.message}`);
      reject(err);
    });

    server.listen(HTTPS_PORT, () => {
      console.log(`[https] Server listening on https://localhost:${HTTPS_PORT}`);
      resolve(server);
    });
  });
}

/**
 * Boot both servers. HTTPS failures are non-fatal; the process falls back to
 * HTTP-only so a bad cert rotation never takes the whole service down.
 *
 * @returns {Promise<{ httpServer: http.Server, httpsServer: https.Server|null }>}
 */
async function startServers() {
  // HTTP is mandatory — let any error propagate.
  const httpServer = await startHttpServer();

  // HTTPS is best-effort — degrade gracefully on failure.
  let httpsServer = null;
  try {
    httpsServer = await startHttpsServer();
  } catch (err) {
    console.warn(
      '[https] Could not start HTTPS server — continuing in HTTP-only mode. ' +
      `Reason: ${err.message}`
    );
  }

  return { httpServer, httpsServer };
}

// Start servers when this file is run directly (not when required in tests).
if (require.main === module) {
  startServers().catch((err) => {
    console.error('[app] Fatal startup error:', err.message);
    process.exit(1);
  });
}

module.exports = { app, startServers };

