    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ── Server startup ────────────────────────────────────────────────────────────

/**
 * Start an HTTP server on HTTP_PORT. This is always created regardless of
 * whether TLS credentials are available.
 */
