  return new Promise((resolve, reject) => {
    const server = http.createServer(app);

    server.on('error', (err) => {
      console.error(`[http] Failed to start on port ${HTTP_PORT}: ${err.message}`);
      reject(err);
    });

    server.listen(HTTP_PORT, () => {
      console.log(`[http]  Server listening  → http://localhost:${HTTP_PORT}`);
      resolve(server);
    });
  });
