function startHttps() {
  return new Promise((resolve, reject) => {
    const server = https.createServer(tlsCredentials, app);

    server.on('error', (err) => {
      console.error(`[https] Failed to start on port ${HTTPS_PORT}: ${err.message}`);
      reject(err);
    });

    server.listen(HTTPS_PORT, () => {
      console.log(`[https] Server listening  → https://localhost:${HTTPS_PORT}`);
      resolve(server);
    });
  });
