 * can close the servers programmatically.
 *
 * @returns {Promise<{ httpServer: http.Server, httpsServer: https.Server | null }>}
 */
async function startServers() {
  const httpServer  = await startHttp();

  let httpsServer = null;
  if (tlsCredentials) {
    httpsServer = await startHttps();
  } else {
    console.log(
      '[https] No TLS credentials found (TLS_CERT_PATH / TLS_KEY_PATH not set ' +
      'or files unreadable) — running HTTP-only.'
    );
