/**
 * config.js
 *
 * Central configuration module.
 *
 * TLS settings are sourced exclusively from environment variables so that no
 * secrets or file-system paths are ever hard-coded:
 *
 *   TLS_CERT_PATH  – absolute (or relative) path to the PEM certificate file
 *   TLS_KEY_PATH   – absolute (or relative) path to the PEM private-key file
 *
 * Both variables must be set for HTTPS to be enabled.  If either is missing
 * the server starts in HTTP-only mode and a clear warning is logged.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ── Ports ────────────────────────────────────────────────────────────────────

const HTTP_PORT  = parseInt(process.env.HTTP_PORT  || '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT || '3443', 10);

// ── TLS ──────────────────────────────────────────────────────────────────────

/**
 * Attempt to load TLS credentials from the paths supplied via environment
 * variables.
 *
 * @returns {{ cert: Buffer, key: Buffer } | null}
 *   A credentials object when both files are readable, otherwise null.
 */
function loadTlsCredentials() {
  const certPath = process.env.TLS_CERT_PATH;
  const keyPath  = process.env.TLS_KEY_PATH;

  // Both variables must be present.
  if (!certPath || !keyPath) {
    return null;
  }

  const resolvedCert = path.resolve(certPath);
  const resolvedKey  = path.resolve(keyPath);

  // Verify the files exist and are readable before attempting fs.readFileSync,
  // so we can emit a precise error message if something is misconfigured.
  for (const [label, filePath] of [['TLS_CERT_PATH', resolvedCert], ['TLS_KEY_PATH', resolvedKey]]) {
    try {
      fs.accessSync(filePath, fs.constants.R_OK);
    } catch {
      throw new Error(
        `TLS configuration error: cannot read file for ${label}: "${filePath}". ` +
        'Verify the path is correct and the process has read permission.'
      );
    }
  }

  return {
    cert: fs.readFileSync(resolvedCert),
    key:  fs.readFileSync(resolvedKey),
  };
}

/**
 * Indicates whether TLS environment variables have been provided.
 * Does NOT verify that the files exist – use loadTlsCredentials() for that.
 *
 * @returns {boolean}
 */
function isTlsConfigured() {
  return Boolean(process.env.TLS_CERT_PATH && process.env.TLS_KEY_PATH);
}

// ── Exports ──────────────────────────────────────────────────────────────────

module.exports = {
  HTTP_PORT,
  HTTPS_PORT,
  isTlsConfigured,
  loadTlsCredentials,
};

/**
 * app.js
 *
 * Express application with optional HTTPS support.
 *
 * Startup behaviour
 * ─────────────────
 * • TLS env vars SET and cert/key files readable
 *     → HTTP  server on HTTP_PORT  (default 3000)
 *     → HTTPS server on HTTPS_PORT (default 3443)
 *
 * • TLS env vars missing OR files unreadable
 *     → HTTP-only server on HTTP_PORT  (default 3000)
 *     → A clear warning is printed so the omission is never silent
 *
 * The module exports { app, startServers } so the servers can be started
 * (and later closed) in tests without side-effects on require().
 */

'use strict';

const http    = require('http');
const https   = require('https');
const express = require('express');

const { HTTP_PORT, HTTPS_PORT, isTlsConfigured, loadTlsCredentials } = require('./config');

// ── Express application ───────────────────────────────────────────────────────

const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ── Server factory ────────────────────────────────────────────────────────────

/**
 * Create and start both servers (or HTTP-only when TLS is unavailable).
 *
 * @returns {{ httpServer: http.Server, httpsServer: https.Server | null }}
 */
function startServers() {
  // ── HTTP (always started) ──────────────────────────────────────────────────
  const httpServer = http.createServer(app);

  httpServer.listen(HTTP_PORT, () => {
    console.log(`[http]  Server listening on http://localhost:${HTTP_PORT}`);
  });

  // ── HTTPS (started only when TLS credentials are available) ───────────────
  let httpsServer = null;

  if (!isTlsConfigured()) {
    // Neither variable is set – expected in local/dev environments.
    console.warn(
      '[https] TLS_CERT_PATH and TLS_KEY_PATH are not set. ' +
      'Starting in HTTP-only mode.'
    );
    return { httpServer, httpsServer };
  }

  // Variables are set; attempt to load the files (throws on misconfiguration).
  let tlsCredentials;
  try {
    tlsCredentials = loadTlsCredentials();
  } catch (err) {
    console.error(`[https] ${err.message}`);
    console.warn('[https] Falling back to HTTP-only mode.');
    return { httpServer, httpsServer };
  }

  httpsServer = https.createServer(
    { cert: tlsCredentials.cert, key: tlsCredentials.key },
    app
  );

  httpsServer.listen(HTTPS_PORT, () => {
    console.log(`[https] Server listening on https://localhost:${HTTPS_PORT}`);
  });

  return { httpServer, httpsServer };
}

// ── Auto-start when this file is run directly ─────────────────────────────────

if (require.main === module) {
  startServers();
}

// ── Exports ───────────────────────────────────────────────────────────────────

module.exports = { app, startServers };

