process.env.TLS_KEY_PATH  = '/nonexistent/key.pem';
try {
  config.loadTlsCredentials();
  console.log('FAIL: should have thrown for missing cert file');
} catch (e) {
  console.assert(e.message.includes('TLS_CERT_PATH'), 'FAIL: error should mention TLS_CERT_PATH');
  console.log('PASS: loadTlsCredentials() throws with useful message for missing cert');
}

