delete process.env.TLS_KEY_PATH;
const creds = config.loadTlsCredentials();
console.assert(creds === null, 'FAIL: should return null when vars unset');
console.log('PASS: loadTlsCredentials() returns null when vars not set');

// ── 5. config.js – PORT defaults ─────────────────────────────────────────────
console.assert(config.HTTP_PORT  === 3000, 'FAIL: HTTP_PORT default should be 3000');
console.assert(config.HTTPS_PORT === 3443, 'FAIL: HTTPS_PORT default should be 3443');
console.log('PASS: HTTP_PORT=3000, HTTPS_PORT=3443 defaults');

// ── 6. app.js – HTTP-only when TLS vars absent ────────────────────────────────
delete process.env.TLS_CERT_PATH;
delete process.env.TLS_KEY_PATH;

const httpListenCalls  = [];
const httpsCreateCalls = [];

// Patch http/https in the require cache
const httpMod  = require('http');
const httpsMod = require('https');
const origHttpCreate  = httpMod.createServer.bind(httpMod);
const origHttpsCreate = httpsMod.createServer.bind(httpsMod);

httpMod.createServer  = (app)         => ({ listen: (p, cb) => { httpListenCalls.push(p);  if(cb) cb(); return {}; } });
httpsMod.createServer = (opts, app)   => { httpsCreateCalls.push(opts); return { listen: (p, cb) => { if(cb) cb(); return {}; } }; };

delete require.cache[require.resolve('./app')];
delete require.cache[require.resolve('./config')]; // reload fresh config
const { startServers } = require('./app');

const { httpServer, httpsServer } = startServers();

console.assert(httpListenCalls.length  === 1,    'FAIL: HTTP server should start once');
console.assert(httpsCreateCalls.length === 0,    'FAIL: HTTPS server must NOT start when certs absent');
console.assert(httpsServer             === null,  'FAIL: httpsServer should be null in HTTP-only mode');
console.log('PASS: HTTP-only mode — no HTTPS server created when TLS vars absent');

httpMod.createServer  = origHttpCreate;
httpsMod.createServer = origHttpsCreate;

console.log('');
console.log('All tests passed.');
