/**
 * config.js
 *
 * Central configuration module.
 *
 * TLS certificate resolution
 * ──────────────────────────
 * Set the following environment variables to enable HTTPS:
 *
 *   TLS_CERT_PATH   – absolute (or cwd-relative) path to the PEM certificate file
 *   TLS_KEY_PATH    – absolute (or cwd-relative) path to the PEM private-key file
 *
 * Both variables must be present and point to readable files for HTTPS to be
 * activated.  If either is missing or unreadable the server falls back to
 * HTTP-only and logs a clear reason so operators can diagnose the issue.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ── Ports ─────────────────────────────────────────────────────────────────────

const HTTP_PORT  = parseInt(process.env.HTTP_PORT  || '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT || '3443', 10);

// ── TLS helper ────────────────────────────────────────────────────────────────

/**
 * Attempt to load TLS credentials from the paths supplied via environment
 * variables.
 *
 * @returns {{ cert: Buffer, key: Buffer }|null}
 *   A credentials object ready to pass to `https.createServer()`, or `null`
 *   when HTTPS cannot / should not be started.
 */
function loadTlsCredentials() {
  const certPath = process.env.TLS_CERT_PATH;
  const keyPath  = process.env.TLS_KEY_PATH;

  // Neither variable set → operator has not configured TLS; silently skip.
  if (!certPath && !keyPath) {
    return null;
  }

  // One variable set without the other → likely a misconfiguration; warn.
  if (!certPath || !keyPath) {
    const missing = !certPath ? 'TLS_CERT_PATH' : 'TLS_KEY_PATH';
    console.warn(
      `[config] HTTPS disabled: ${missing} is not set. ` +
      'Both TLS_CERT_PATH and TLS_KEY_PATH must be provided.'
    );
    return null;
  }

  // Resolve paths relative to the current working directory when not absolute.
  const resolvedCert = path.resolve(process.cwd(), certPath);
  const resolvedKey  = path.resolve(process.cwd(), keyPath);

  // Validate that each file exists and is readable before attempting to load.
  for (const [label, filePath] of [['TLS_CERT_PATH', resolvedCert], ['TLS_KEY_PATH', resolvedKey]]) {
    try {
      fs.accessSync(filePath, fs.constants.R_OK);
    } catch {
      console.warn(
        `[config] HTTPS disabled: cannot read file for ${label}: "${filePath}". ` +
        'Check that the path is correct and the process has read permission.'
      );
      return null;
    }
  }

  // Both files are present and readable — load them.
  try {
    return {
      cert: fs.readFileSync(resolvedCert),
      key:  fs.readFileSync(resolvedKey),
    };
  } catch (err) {
    console.warn(`[config] HTTPS disabled: failed to read TLS files — ${err.message}`);
    return null;
  }
}

// ── Exported configuration ────────────────────────────────────────────────────

module.exports = {
  HTTP_PORT,
  HTTPS_PORT,
  /**
   * TLS credentials ({ cert, key }) when both env vars are set and the files
   * are readable; `null` otherwise.
   */
  tlsCredentials: loadTlsCredentials(),
};

/**
 * app.js
 *
 * Express application with dual HTTP / HTTPS support.
 *
 * Behaviour
 * ─────────
 *  • HTTP  always starts on HTTP_PORT  (default 3000).
 *  • HTTPS starts on HTTPS_PORT (default 3443) only when valid TLS credentials
 *    are available via TLS_CERT_PATH / TLS_KEY_PATH (see config.js).
 *  • When certs are absent or unreadable the server falls back to HTTP-only
 *    and logs a clear message so operators know what to fix.
 */

'use strict';

const http    = require('http');
const https   = require('https');
const express = require('express');
const { HTTP_PORT, HTTPS_PORT, tlsCredentials } = require('./config');

// ── Express application ───────────────────────────────────────────────────────

const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ── Server startup ────────────────────────────────────────────────────────────

/**
 * Start the HTTP server (always).
 */
function startHttp() {
  const server = http.createServer(app);

  server.listen(HTTP_PORT, () => {
    console.log(`[http]  Server listening on http://localhost:${HTTP_PORT}`);
  });

  server.on('error', (err) => {
    console.error(`[http]  Failed to start HTTP server: ${err.message}`);
    process.exit(1);
  });

  return server;
}

/**
 * Start the HTTPS server when TLS credentials are available.
 * Returns the server instance, or null when HTTPS is skipped.
 */
function startHttps() {
  if (!tlsCredentials) {
    console.log(
      '[https] TLS credentials not configured — ' +
      'set TLS_CERT_PATH and TLS_KEY_PATH to enable HTTPS.'
    );
    return null;
  }

  const server = https.createServer(tlsCredentials, app);

  server.listen(HTTPS_PORT, () => {
    console.log(`[https] Server listening on https://localhost:${HTTPS_PORT}`);
  });

  server.on('error', (err) => {
    console.error(`[https] Failed to start HTTPS server: ${err.message}`);
    // A failed HTTPS bind is non-fatal; HTTP remains available.
  });

  return server;
}

const httpServer  = startHttp();
const httpsServer = startHttps();

// ── Exports (useful for testing) ──────────────────────────────────────────────

module.exports = { app, httpServer, httpsServer };

