/**
 * config.js
 *
 * Central configuration module.
 * TLS is opt-in: set TLS_CERT_PATH and TLS_KEY_PATH environment variables to
 * enable HTTPS. When either variable is absent the application starts in
 * HTTP-only mode without error.
 */

'use strict';

const fs = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// Port configuration
// ---------------------------------------------------------------------------

const HTTP_PORT  = parseInt(process.env.HTTP_PORT  ?? '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT ?? '3443', 10);

// ---------------------------------------------------------------------------
// TLS configuration
// ---------------------------------------------------------------------------

/**
 * Attempt to load TLS credentials from the paths supplied via environment
 * variables.  Returns a populated `tlsOptions` object when both files are
 * readable, or `null` when certs are not configured / not yet available.
 *
 * @returns {{ cert: Buffer, key: Buffer } | null}
 */
function loadTlsOptions() {
  const certPath = process.env.TLS_CERT_PATH;
  const keyPath  = process.env.TLS_KEY_PATH;

  // Neither variable set — caller requested HTTP-only mode.
  if (!certPath && !keyPath) {
    return null;
  }

  // One variable set but not the other — likely a misconfiguration; warn and
  // fall back to HTTP-only so the server still starts.
  if (!certPath || !keyPath) {
    const missing = !certPath ? 'TLS_CERT_PATH' : 'TLS_KEY_PATH';
    console.warn(
      `[config] WARNING: ${missing} is not set. ` +
      'Both TLS_CERT_PATH and TLS_KEY_PATH must be provided to enable HTTPS. ' +
      'Falling back to HTTP-only.'
    );
    return null;
  }

  const resolvedCert = path.resolve(certPath);
  const resolvedKey  = path.resolve(keyPath);

  // Validate that both files actually exist and are readable before handing
  // the paths to the HTTPS server (gives a clear error instead of a cryptic
  // ENOENT from deep inside the tls module).
  for (const [label, filePath] of [['TLS_CERT_PATH', resolvedCert], ['TLS_KEY_PATH', resolvedKey]]) {
    try {
      fs.accessSync(filePath, fs.constants.R_OK);
    } catch {
      console.warn(
        `[config] WARNING: Cannot read file for ${label}: "${filePath}". ` +
        'Falling back to HTTP-only.'
      );
      return null;
    }
  }

  try {
    return {
      cert: fs.readFileSync(resolvedCert),
      key:  fs.readFileSync(resolvedKey),
    };
  } catch (err) {
    console.warn(
      `[config] WARNING: Failed to load TLS files — ${err.message}. ` +
      'Falling back to HTTP-only.'
    );
    return null;
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  HTTP_PORT,
  HTTPS_PORT,
  loadTlsOptions,
};

// app.js
//
// Starts an Express application on HTTP (port 3000) and, when TLS credentials
// are available via environment variables, also on HTTPS (port 3443).
// Port numbers and cert paths are managed by config.js.

'use strict';

const http  = require('http');
const https = require('https');

const express = require('express');
const { HTTP_PORT, HTTPS_PORT, loadTlsOptions } = require('./config');

// ---------------------------------------------------------------------------
// Express application
// ---------------------------------------------------------------------------

const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ---------------------------------------------------------------------------
// Server startup
// ---------------------------------------------------------------------------

/**
 * Create and start the HTTP server (always).
 */
function startHttp() {
  return new Promise((resolve, reject) => {
    const server = http.createServer(app);

    server.on('error', reject);

    server.listen(HTTP_PORT, () => {
      console.log(`[http]  Server listening on http://localhost:${HTTP_PORT}`);
      resolve(server);
    });
  });
}

/**
 * Create and start the HTTPS server (only when TLS options are available).
 *
 * @param {{ cert: Buffer, key: Buffer }} tlsOptions
 */
function startHttps(tlsOptions) {
  return new Promise((resolve, reject) => {
    const server = https.createServer(tlsOptions, app);

    server.on('error', reject);

    server.listen(HTTPS_PORT, () => {
      console.log(`[https] Server listening on https://localhost:${HTTPS_PORT}`);
      resolve(server);
    });
  });
}

/**
 * Boot sequence:
 *  1. Always start HTTP.
 *  2. Check for TLS credentials via config.loadTlsOptions().
 *  3. If credentials are present, also start HTTPS; otherwise log the
 *     HTTP-only notice and continue normally.
 */
async function start() {
  const servers = [];

  // HTTP — always required.
  servers.push(await startHttp());

  // HTTPS — conditional on TLS credentials being configured and readable.
  const tlsOptions = loadTlsOptions();

  if (tlsOptions) {
    servers.push(await startHttps(tlsOptions));
  } else {
    console.log(
      '[config] TLS credentials not configured — running in HTTP-only mode. ' +
      'Set TLS_CERT_PATH and TLS_KEY_PATH to enable HTTPS.'
    );
  }

  return servers;
}

// Start the server(s) only when this file is run directly, not when it is
// require()'d by tests or other modules.
if (require.main === module) {
  start().catch((err) => {
    console.error('[startup] Fatal error:', err);
    process.exit(1);
  });
}

module.exports = { app, start };

