  const keyPath  = process.env.TLS_KEY_PATH;

  // Neither variable set — caller requested HTTP-only mode.
  if (!certPath && !keyPath) {
    return null;
  }

  // One variable set but not the other — likely a misconfiguration; warn and
  // fall back to HTTP-only so the server still starts.
  if (!certPath || !keyPath) {
    const missing = !certPath ? 'TLS_CERT_PATH' : 'TLS_KEY_PATH';
    console.warn(
      `[config] WARNING: ${missing} is not set. ` +
      'Both TLS_CERT_PATH and TLS_KEY_PATH must be provided to enable HTTPS. ' +
      'Falling back to HTTP-only.'
    );
    return null;
  }

  const resolvedCert = path.resolve(certPath);
  const resolvedKey  = path.resolve(keyPath);

  // Validate that both files actually exist and are readable before handing
  // the paths to the HTTPS server (gives a clear error instead of a cryptic
  // ENOENT from deep inside the tls module).
  for (const [label, filePath] of [['TLS_CERT_PATH', resolvedCert], ['TLS_KEY_PATH', resolvedKey]]) {
    try {
      fs.accessSync(filePath, fs.constants.R_OK);
    } catch {
      console.warn(
        `[config] WARNING: Cannot read file for ${label}: "${filePath}". ` +
        'Falling back to HTTP-only.'
      );
      return null;
    }
  }

  try {
    return {
      cert: fs.readFileSync(resolvedCert),
      key:  fs.readFileSync(resolvedKey),
    };
  } catch (err) {
    console.warn(
      `[config] WARNING: Failed to load TLS files — ${err.message}. ` +
      'Falling back to HTTP-only.'
    );
    return null;
  }
}

