// app.js
//
// Starts an Express application on HTTP (port 3000) and, when TLS credentials
// are available via environment variables, also on HTTPS (port 3443).
// Port numbers and cert paths are managed by config.js.

'use strict';

const http  = require('http');
const https = require('https');

const express = require('express');
const { HTTP_PORT, HTTPS_PORT, loadTlsOptions } = require('./config');

// ---------------------------------------------------------------------------
// Express application
// ---------------------------------------------------------------------------

const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ---------------------------------------------------------------------------
// Server startup
// ---------------------------------------------------------------------------

/**
 * Create and start the HTTP server (always).
 */
function startHttp() {
  return new Promise((resolve, reject) => {
    const server = http.createServer(app);

    server.on('error', reject);

    server.listen(HTTP_PORT, () => {
      console.log(`[http]  Server listening on http://localhost:${HTTP_PORT}`);
      resolve(server);
    });
  });
}

/**
 * Create and start the HTTPS server (only when TLS options are available).
 *
 * @param {{ cert: Buffer, key: Buffer }} tlsOptions
 */
function startHttps(tlsOptions) {
  return new Promise((resolve, reject) => {
    const server = https.createServer(tlsOptions, app);

    server.on('error', reject);

    server.listen(HTTPS_PORT, () => {
      console.log(`[https] Server listening on https://localhost:${HTTPS_PORT}`);
      resolve(server);
    });
  });
}

/**
 * Boot sequence:
 *  1. Always start HTTP.
 *  2. Check for TLS credentials via config.loadTlsOptions().
 *  3. If credentials are present, also start HTTPS; otherwise log the
 *     HTTP-only notice and continue normally.
 */
async function start() {
  const servers = [];

  // HTTP — always required.
  servers.push(await startHttp());

  // HTTPS — conditional on TLS credentials being configured and readable.
  const tlsOptions = loadTlsOptions();

  if (tlsOptions) {
    servers.push(await startHttps(tlsOptions));
  } else {
    console.log(
      '[config] TLS credentials not configured — running in HTTP-only mode. ' +
      'Set TLS_CERT_PATH and TLS_KEY_PATH to enable HTTPS.'
    );
  }

  return servers;
}

// Start the server(s) only when this file is run directly, not when it is
// require()'d by tests or other modules.
if (require.main === module) {
  start().catch((err) => {
    console.error('[startup] Fatal error:', err);
    process.exit(1);
  });
}

module.exports = { app, start };

