/**
 * config.js
 *
 * Central configuration module.
 * TLS settings are read exclusively from environment variables so that no
 * secrets or file-system paths are ever hard-coded in source.
 *
 * Expected environment variables
 * ─────────────────────────────
 *   TLS_CERT_PATH  – Absolute (or relative) path to the PEM-encoded TLS
 *                    certificate file (i.e. fullchain.pem / server.crt).
 *   TLS_KEY_PATH   – Absolute (or relative) path to the PEM-encoded private
 *                    key file (i.e. privkey.pem / server.key).
 *
 * Both variables must be set for HTTPS to be enabled.  If either is absent
 * the application falls back to HTTP-only mode, which is logged as a warning.
 */

'use strict';

const path = require('path');

// ── Port configuration ────────────────────────────────────────────────────────

const HTTP_PORT  = parseInt(process.env.HTTP_PORT  || '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT || '3443', 10);

// ── TLS configuration ─────────────────────────────────────────────────────────

const TLS_CERT_PATH = process.env.TLS_CERT_PATH
  ? path.resolve(process.env.TLS_CERT_PATH)
  : null;

const TLS_KEY_PATH = process.env.TLS_KEY_PATH
  ? path.resolve(process.env.TLS_KEY_PATH)
  : null;

/**
 * Whether both TLS paths have been supplied.
 * The actual files are validated at start-up time in app.js, not here, so
 * this module stays side-effect-free and easy to unit-test.
 */
const TLS_ENABLED = Boolean(TLS_CERT_PATH && TLS_KEY_PATH);

// ── Exported configuration object ─────────────────────────────────────────────

module.exports = {
  HTTP_PORT,
  HTTPS_PORT,
  TLS_ENABLED,
  tls: {
    certPath: TLS_CERT_PATH,
    keyPath:  TLS_KEY_PATH,
  },
};

/**
 * app.js
 *
 * Express application with optional HTTPS support.
 *
 * Start-up behaviour
