/**
 * config.js
 *
 * Central configuration module.
 * TLS is opt-in: set TLS_CERT_PATH and TLS_KEY_PATH in the environment to
 * enable HTTPS.  All other values have safe defaults so the app can start
 * without any environment variables present.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// Helper: resolve a path string and verify the file is readable.
// Returns the resolved absolute path on success, or null on any failure.
// ---------------------------------------------------------------------------
function resolveFilePath(envValue, label) {
  if (!envValue || !envValue.trim()) {
    return null;
  }

  const resolved = path.resolve(envValue.trim());

  try {
    fs.accessSync(resolved, fs.constants.R_OK);
    return resolved;
  } catch (err) {
    console.warn(
      `[config] Warning: ${label} points to "${resolved}" which is not readable (${err.message}). HTTPS will be disabled.`
    );
    return null;
  }
}

// ---------------------------------------------------------------------------
// Ports
// ---------------------------------------------------------------------------
const HTTP_PORT  = parseInt(process.env.HTTP_PORT  || '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT || '3443', 10);

// ---------------------------------------------------------------------------
// TLS – resolve paths from environment variables
// ---------------------------------------------------------------------------
const certPath = resolveFilePath(process.env.TLS_CERT_PATH, 'TLS_CERT_PATH');
const keyPath  = resolveFilePath(process.env.TLS_KEY_PATH,  'TLS_KEY_PATH');

// TLS is only considered available when BOTH files can be read.
const tlsAvailable = certPath !== null && keyPath !== null;

// Lazily load file contents only when TLS is actually available, so that the
// app starts cleanly in HTTP-only environments without touching the FS again.
let tlsOptions = null;
if (tlsAvailable) {
  try {
    tlsOptions = {
      cert: fs.readFileSync(certPath),
      key:  fs.readFileSync(keyPath),
    };
  } catch (err) {
    // Unlikely after accessSync succeeded, but guard anyway.
    console.warn(
      `[config] Warning: Failed to read TLS files at runtime (${err.message}). HTTPS will be disabled.`
    );
  }
}

// ---------------------------------------------------------------------------
// Exported configuration object (immutable via Object.freeze)
// ---------------------------------------------------------------------------
const config = Object.freeze({
  /** Port for the plain-HTTP server. */
  httpPort: HTTP_PORT,

  /** Port for the HTTPS server (only used when tlsAvailable is true). */
  httpsPort: HTTPS_PORT,

  /**
   * True when both TLS_CERT_PATH and TLS_KEY_PATH resolve to readable files
   * and their contents were loaded successfully.
   */
  tlsAvailable: tlsAvailable && tlsOptions !== null,

  /**
   * Options object passed directly to https.createServer().
   * Contains `cert` and `key` Buffers, or null when TLS is unavailable.
   */
  tlsOptions,
});

module.exports = config;

/**
 * app.js
 *
 * Express application with dual HTTP / HTTPS support.
 *
 * Behaviour:
 *  - Always starts an HTTP server on HTTP_PORT (default 3000).
 *  - When TLS_CERT_PATH and TLS_KEY_PATH are set and point to readable files,
 *    also starts an HTTPS server on HTTPS_PORT (default 3443).
 *  - Falls back to HTTP-only when TLS credentials are unavailable.
 */

'use strict';

const http    = require('http');
const https   = require('https');
const express = require('express');
const config  = require('./config');

const app = express();

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ---------------------------------------------------------------------------
// Server startup  (skipped when this file is required by tests)
// ---------------------------------------------------------------------------

/* istanbul ignore next */
if (require.main === module) {
  // --- HTTP -----------------------------------------------------------------
  const httpServer = http.createServer(app);

  httpServer.listen(config.httpPort, () => {
    console.log(`[http]  Server listening on http://localhost:${config.httpPort}`);
  });

  httpServer.on('error', (err) => {
    console.error(`[http]  Failed to start HTTP server: ${err.message}`);
    process.exit(1);
  });

  // --- HTTPS (optional) -----------------------------------------------------
  if (config.tlsAvailable) {
    const httpsServer = https.createServer(config.tlsOptions, app);

    httpsServer.listen(config.httpsPort, () => {
      console.log(`[https] Server listening on https://localhost:${config.httpsPort}`);
    });

    httpsServer.on('error', (err) => {
      console.error(`[https] Failed to start HTTPS server: ${err.message}`);
      // HTTPS failure is non-fatal – HTTP server continues running.
      console.warn('[https] Continuing with HTTP-only mode.');
    });
  } else {
    console.log(
      '[https] TLS certificates not configured or unreadable – running in HTTP-only mode.\n' +
      '        Set TLS_CERT_PATH and TLS_KEY_PATH to enable HTTPS.'
    );
  }
}

module.exports = app;

