/**
 * config.js
 *
 * Central configuration module. TLS settings are read exclusively from
 * environment variables so that no secrets are ever hard-coded.
 *
 * Environment variables
 * ─────────────────────
 *   TLS_CERT_PATH  – Absolute (or relative) path to the PEM-encoded
 *                    TLS certificate file (e.g. /etc/tls/server.crt).
 *   TLS_KEY_PATH   – Absolute (or relative) path to the PEM-encoded
 *                    private key file   (e.g. /etc/tls/server.key).
 *
 * Both variables must be set for HTTPS to be enabled.  If either is
 * missing the server starts in HTTP-only mode.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ── Ports ────────────────────────────────────────────────────────────────────

const HTTP_PORT  = parseInt(process.env.HTTP_PORT  || '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT || '3443', 10);

// ── TLS certificate loader ───────────────────────────────────────────────────

/**
 * Attempts to load TLS credentials from the paths supplied via environment
 * variables.
 *
 * @returns {{ cert: Buffer, key: Buffer }|null}
 *   An object containing the raw cert and key buffers when both paths are
 *   configured and the files can be read, or `null` otherwise.
 */
function loadTlsCredentials() {
  const certPath = process.env.TLS_CERT_PATH;
  const keyPath  = process.env.TLS_KEY_PATH;

  // Both variables must be present.
  if (!certPath || !keyPath) {
    return null;
  }

  const resolvedCert = path.resolve(certPath);
  const resolvedKey  = path.resolve(keyPath);

  try {
    const cert = fs.readFileSync(resolvedCert);
    const key  = fs.readFileSync(resolvedKey);
    return { cert, key };
  } catch (err) {
    // Surface a clear message so operators can diagnose path/permission issues.
    console.error(
      `[config] Failed to load TLS credentials: ${err.message}\n` +
      `  TLS_CERT_PATH → ${resolvedCert}\n` +
      `  TLS_KEY_PATH  → ${resolvedKey}\n` +
      '  Falling back to HTTP-only mode.'
    );
    return null;
  }
}

// ── Exported configuration ───────────────────────────────────────────────────

module.exports = {
  HTTP_PORT,
  HTTPS_PORT,

  /**
   * TLS credentials object `{ cert, key }`, or `null` when unavailable.
   * Evaluated once at start-up; the result is cached on this export.
   */
  tls: loadTlsCredentials(),
};

/**
 * app.js
 *
 * Express application with dual HTTP / HTTPS support.
 *
 * Start-up behaviour
 * ──────────────────
 *   • HTTP  is always started on HTTP_PORT  (default 3000).
 *   • HTTPS is started on HTTPS_PORT (default 3443) only when valid TLS
 *     certificate + key paths are supplied via the TLS_CERT_PATH and
 *     TLS_KEY_PATH environment variables.  See config.js for details.
 *   • If the TLS files are configured but cannot be read, the server
 *     falls back to HTTP-only and logs a descriptive error.
 */

'use strict';

const http    = require('http');
const https   = require('https');
const express = require('express');
const config  = require('./config');

const app = express();

// ── Routes ───────────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ── Server start-up ──────────────────────────────────────────────────────────

/**
 * Starts the HTTP and (optionally) HTTPS servers.
 *
 * Separating this logic into a named function keeps start-up side-effects out
 * of the module scope, making the app easier to test — callers can `require`
 * the module without triggering a `listen`.
 *
 * @returns {{ httpServer: http.Server, httpsServer: https.Server|null }}
 */
function startServers() {
  // Always start HTTP.
  const httpServer = http.createServer(app);
  httpServer.listen(config.HTTP_PORT, () => {
    console.log(`[http]  Server listening on http://localhost:${config.HTTP_PORT}`);
  });

  // Start HTTPS only when credentials are available.
  let httpsServer = null;

  if (config.tls) {
    httpsServer = https.createServer(config.tls, app);
    httpsServer.listen(config.HTTPS_PORT, () => {
      console.log(`[https] Server listening on https://localhost:${config.HTTPS_PORT}`);
    });
  } else {
    console.log(
      '[https] TLS credentials not configured — running in HTTP-only mode.\n' +
      '        Set TLS_CERT_PATH and TLS_KEY_PATH to enable HTTPS.'
    );
  }

  return { httpServer, httpsServer };
}

// Only bind to ports when this file is run directly (`node app.js`).
// When it is `require()`-d by tests, no ports are opened.
if (require.main === module) {
  startServers();
}

module.exports = { app, startServers };

