// config.js — centralised application configuration
// TLS certificate paths are read from environment variables:
//   TLS_CERT_PATH  – path to the PEM-encoded certificate file
//   TLS_KEY_PATH   – path to the PEM-encoded private key file
//
// Both variables must be set AND the files must be readable for HTTPS to be
// enabled.  If either is missing or unreadable the server falls back to
// HTTP-only mode so the application still starts in environments where certs
// have not been provisioned (e.g. local development, CI).

'use strict';

const fs = require('fs');

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Returns true when `filePath` is a non-empty string that points to a file
 * that can be read by the current process.  Any I/O error is swallowed so
 * callers receive a simple boolean rather than an exception.
 *
 * @param {string | undefined} filePath
 * @returns {boolean}
 */
function isReadableFile(filePath) {
  if (!filePath || typeof filePath !== 'string' || filePath.trim() === '') {
    return false;
  }
  try {
    fs.accessSync(filePath, fs.constants.R_OK);
    return true;
  } catch {
    return false;
  }
}

// ---------------------------------------------------------------------------
// TLS configuration
// ---------------------------------------------------------------------------

const TLS_CERT_PATH = process.env.TLS_CERT_PATH;
const TLS_KEY_PATH  = process.env.TLS_KEY_PATH;

const certAvailable = isReadableFile(TLS_CERT_PATH);
const keyAvailable  = isReadableFile(TLS_KEY_PATH);

/**
 * tlsConfig is `null` when certificates are unavailable (HTTP-only fallback).
 * When both files are present it is an object whose `cert` and `key`
 * properties are `Buffer` values suitable for passing directly to
 * `https.createServer()`.
 *
 * Reading the files here (at require-time) means any I/O error surfaces
 * immediately on start-up rather than at the first HTTPS request.
 *
 * @type {{ cert: Buffer, key: Buffer } | null}
 */
const tlsConfig = (certAvailable && keyAvailable)
  ? {
      cert: fs.readFileSync(TLS_CERT_PATH),
      key:  fs.readFileSync(TLS_KEY_PATH),
    }
  : null;

// ---------------------------------------------------------------------------
// Port configuration
// ---------------------------------------------------------------------------

const HTTP_PORT  = parseInt(process.env.HTTP_PORT  || '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT || '3443', 10);

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  /** Port the HTTP server will listen on (default 3000). */
  HTTP_PORT,

  /** Port the HTTPS server will listen on (default 3443). */
  HTTPS_PORT,

  /**
   * TLS options object (`{ cert, key }`) ready for `https.createServer()`, or
   * `null` when TLS is not configured.  Consumers should treat a `null` value
   * as "HTTP-only mode".
   */
  tlsConfig,

  /**
   * Convenience boolean — `true` when a valid TLS configuration was loaded.
   * Use this for conditional logic instead of testing `tlsConfig !== null`.
   */
  tlsEnabled: tlsConfig !== null,
};

// app.js — Express application with optional HTTPS support
//
// Servers started:
//   • HTTP  — always, on HTTP_PORT  (default 3000)
//   • HTTPS — only when TLS_CERT_PATH and TLS_KEY_PATH env vars are set and
//             the files they point to are readable, on HTTPS_PORT (default 3443)
//
// Set TLS_CERT_PATH and TLS_KEY_PATH in the environment (or a .env loader of
// your choice) to enable HTTPS.  The server falls back to HTTP-only mode when
// the variables are absent or the files cannot be read.

'use strict';

const http  = require('http');
const https = require('https');

const express = require('express');
const { HTTP_PORT, HTTPS_PORT, tlsConfig, tlsEnabled } = require('./config');

const app = express();

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ---------------------------------------------------------------------------
// Server startup
// ---------------------------------------------------------------------------

// Always start the HTTP server.
const httpServer = http.createServer(app);

httpServer.listen(HTTP_PORT, () => {
  console.log(`HTTP  server listening on http://localhost:${HTTP_PORT}`);
});

// Conditionally start the HTTPS server when certificates are available.
if (tlsEnabled) {
  const httpsServer = https.createServer(tlsConfig, app);

  httpsServer.listen(HTTPS_PORT, () => {
    console.log(`HTTPS server listening on https://localhost:${HTTPS_PORT}`);
  });
} else {
  console.warn(
    'TLS certificates not configured (TLS_CERT_PATH / TLS_KEY_PATH unset or ' +
    'unreadable) — running in HTTP-only mode.'
  );
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = app;

