/**
 * config.js
 *
 * Central configuration module.
 * TLS certificate paths are read exclusively from the environment variables
 * TLS_CERT_PATH and TLS_KEY_PATH so that secrets never live in source code.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ── Ports ──────────────────────────────────────────────────────────────────────
const HTTP_PORT  = parseInt(process.env.HTTP_PORT  || '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT || '3443', 10);

// ── TLS ────────────────────────────────────────────────────────────────────────
/**
 * Attempt to load TLS credentials from the paths supplied via environment
 * variables.  Returns `null` when either variable is absent or either file
 * cannot be read, allowing the application to degrade gracefully to HTTP-only.
 *
 * @returns {{ cert: Buffer, key: Buffer } | null}
 */
function loadTlsCredentials() {
  const certPath = process.env.TLS_CERT_PATH;
  const keyPath  = process.env.TLS_KEY_PATH;

  // Both variables must be present.
  if (!certPath || !keyPath) {
    return null;
  }

  const resolvedCert = path.resolve(certPath);
  const resolvedKey  = path.resolve(keyPath);

  try {
    const cert = fs.readFileSync(resolvedCert);
    const key  = fs.readFileSync(resolvedKey);
    return { cert, key };
  } catch (err) {
    // Surface a clear warning instead of a cryptic crash.
    console.warn(
      '[config] Warning: TLS_CERT_PATH / TLS_KEY_PATH are set but the files ' +
      `could not be read — falling back to HTTP-only.\n  Reason: ${err.message}`
    );
    return null;
  }
}

module.exports = {
  HTTP_PORT,
  HTTPS_PORT,
  /** Resolved TLS credentials, or `null` if unavailable. */
  tls: loadTlsCredentials(),
};

/**
 * app.js
 *
 * Express application with dual HTTP / HTTPS support.
 *
 * Behaviour
 * ─────────
 *  • Always starts an HTTP server on HTTP_PORT (default 3000).
 *  • When TLS credentials are available (TLS_CERT_PATH + TLS_KEY_PATH env vars
 *    point to readable files), also starts an HTTPS server on HTTPS_PORT
 *    (default 3443).
 *  • When credentials are missing or unreadable, the process continues with
 *    HTTP-only and logs a clear warning — it does NOT crash.
 */

'use strict';

const http    = require('http');
const https   = require('https');
const express = require('express');
const config  = require('./config');

// ── Express application ────────────────────────────────────────────────────────
const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ── Server startup (only when this file is run directly) ──────────────────────
if (require.main === module) {
  startServers();
}

/**
 * Creates and starts the HTTP (and optionally HTTPS) server(s).
 * Exported so tests can invoke it independently if needed.
 *
 * @returns {{ httpServer: http.Server, httpsServer: https.Server | null }}
 */
function startServers() {
  // — HTTP ————————————————————————————————————————————————————————————————————
  const httpServer = http.createServer(app);

  httpServer.listen(config.HTTP_PORT, () => {
    console.log(`[http]  Server listening on http://localhost:${config.HTTP_PORT}`);
  });

  // — HTTPS (conditional) ————————————————————————————————————————————————————
  let httpsServer = null;

  if (config.tls) {
    httpsServer = https.createServer(
      { cert: config.tls.cert, key: config.tls.key },
      app
    );

    httpsServer.listen(config.HTTPS_PORT, () => {
      console.log(`[https] Server listening on https://localhost:${config.HTTPS_PORT}`);
    });
  } else {
    console.warn(
      '[https] TLS credentials not available — running HTTP-only. ' +
      'Set TLS_CERT_PATH and TLS_KEY_PATH to enable HTTPS.'
    );
  }

  return { httpServer, httpsServer };
}

module.exports = { app, startServers };

