// config.js — centralised configuration module
// TLS certificate paths are read from environment variables:
//   TLS_CERT_PATH  — path to the PEM-encoded certificate (or certificate chain)
//   TLS_KEY_PATH   — path to the PEM-encoded private key
//
// Both variables must be set for HTTPS to be enabled.  If either is absent the
// server falls back to HTTP-only mode.

'use strict';

const fs   = require('fs');
const path = require('path');

