// config.js — centralised application configuration
//
// TLS configuration is opt-in: the server reads certificate paths from
// environment variables and validates that both files exist and are readable
// before advertising HTTPS support.  If either path is missing or unreadable
// the application falls back to HTTP-only mode so that local / CI environments
// without certificates are never broken.

'use strict';

const fs   = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// Ports
// ---------------------------------------------------------------------------
const HTTP_PORT  = parseInt(process.env.HTTP_PORT  || '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT || '3443', 10);

// ---------------------------------------------------------------------------
// TLS helpers
// ---------------------------------------------------------------------------

/**
 * Resolve an environment variable to an absolute path and verify the file is
 * readable.  Returns the resolved path on success, or null when the variable
 * is absent / the file cannot be accessed.
 *
 * @param {string} envVar  - Name of the environment variable holding the path.
 * @param {string} label   - Human-readable label used in log messages.
 * @returns {string|null}
 */
function resolveFilePath(envVar, label) {
  const raw = process.env[envVar];

  if (!raw || raw.trim() === '') {
    console.warn(`[config] ${envVar} is not set — ${label} unavailable`);
    return null;
  }

  const resolved = path.resolve(raw.trim());

  try {
    fs.accessSync(resolved, fs.constants.R_OK);
    return resolved;
  } catch (err) {
    console.warn(
      `[config] ${envVar} points to "${resolved}" which is not readable ` +
      `(${err.code}) — ${label} unavailable`
    );
    return null;
  }
}

/**
 * Build the TLS configuration object expected by Node's https.createServer().
 * Returns null when either certificate file is unavailable, triggering
 * HTTP-only mode in the caller.
 *
 * @returns {{ cert: Buffer, key: Buffer } | null}
 */
function buildTlsConfig() {
  const certPath = resolveFilePath('TLS_CERT_PATH', 'TLS certificate');
  const keyPath  = resolveFilePath('TLS_KEY_PATH',  'TLS private key');

  if (!certPath || !keyPath) {
    return null;
  }

  try {
    return {
      cert: fs.readFileSync(certPath),
      key:  fs.readFileSync(keyPath),
    };
  } catch (err) {
    console.error(`[config] Failed to read TLS files: ${err.message}`);
    return null;
  }
}

// ---------------------------------------------------------------------------
// Exported configuration
// ---------------------------------------------------------------------------
const tls = buildTlsConfig();

module.exports = {
  HTTP_PORT,
  HTTPS_PORT,

  /** Populated with { cert, key } buffers when both TLS files are readable. */
  tls,

  /** Convenience flag — true when the server should also bind an HTTPS port. */
  tlsEnabled: tls !== null,
};

// app.js — Express application with dual HTTP / HTTPS support
//
// Behaviour
// ─────────
//  • Always starts an HTTP server on HTTP_PORT (default 3000).
//  • When TLS_CERT_PATH and TLS_KEY_PATH are set and readable, also starts an
//    HTTPS server on HTTPS_PORT (default 3443).
//  • Falls back to HTTP-only when certificates are missing or unreadable —
//    no crash, just a clear warning in the logs.

'use strict';

const http    = require('http');
const https   = require('https');
const express = require('express');
const config  = require('./config');

// ---------------------------------------------------------------------------
// Express application
// ---------------------------------------------------------------------------
const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ---------------------------------------------------------------------------
// Server startup — only run when this file is executed directly so that test
// suites that require() the module do not open real ports.
// ---------------------------------------------------------------------------
if (require.main === module) {
  // Always start HTTP
  http.createServer(app).listen(config.HTTP_PORT, () => {
    console.log(`[http]  Server listening on http://localhost:${config.HTTP_PORT}`);
  });

  // Conditionally start HTTPS
  if (config.tlsEnabled) {
    https.createServer(config.tls, app).listen(config.HTTPS_PORT, () => {
      console.log(`[https] Server listening on https://localhost:${config.HTTPS_PORT}`);
    });
  } else {
    console.warn(
      '[https] TLS certificates not available — running HTTP-only. ' +
      'Set TLS_CERT_PATH and TLS_KEY_PATH to enable HTTPS.'
    );
  }
}

module.exports = app;

